Definition recycle_sec_mid2 (L S Zr : list (word * word)) (mo : Model) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo a msz nres nch idx pa lst TSD CTX TH : Z) (chunks : list Z) (g : word) (b244 : byte)
    (msF' : machine_state) (mo' : Model) : Prop :=
  exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
       lzok bsegs L S Zr (mkCfg msF' mo')
    /\ restrict L S msF'
       = MS (mkR (wz 0x52a8c) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz a) (wz a) a0 a1 a2 a3 a4 a5 a6 a7
                 (wz msz) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
            F (Z_to_bv 64 0x52a8c) fc None m' (seg_rom bsegs)
    /\ ps0_model mo a msz mo'
    /\ munch (rs_W lo sp a msz pa nch lst TH) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ SENV tp TSD CTX TH m' /\ RENV g b244 m'
    /\ stk bsegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells bsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m' 1221016 [C8 (wz 4096); C8 (wz pa); C8 (wz pa)]
    /\ rw_cells bsegs m' 1221064 [C8 (wz nres); C8 (wz (nch - 1)); C8 (wz 0)]
    /\ stk bsegs m' 1221088 1221632 /\ rw_cells bsegs m' 1221632 [C8 (wz 0)] /\ stk bsegs m' 1221640 1221680
    /\ u64arr bsegs m' pa (wlist (rs_chunks chunks idx nch lst))
    /\ rw_cells bsegs m' a [C8 (wz a); C8 (wz msz)]
    /\ rw_cells bsegs m' (lst + 24) [C8 (wz idx)]
    /\ stk bsegs m' (TH + 2800) (TH + 3168)
    /\ u8arr bsegs m' (sh a) (repeat (b8 0) (Z.to_nat (msz / 8))).

(* [comment removed for export] *)
Definition recycle_sec_post (L S Zr : list (word * word)) (mo : Model) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo a msz nres nch idx pa lst TSD CTX TH : Z) (chunks : list Z) (g : word) (b244 : byte)
    (msF' : machine_state) (mo' : Model) : Prop :=
  exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
       lzok bsegs (rs_L L a msz) S Zr (mkCfg msF' mo')
    /\ restrict (rs_L L a msz) S msF'
       = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ rs_model mo a msz mo'
    /\ munch (rs_W lo sp a msz pa nch lst TH) m m' /\ wmono_out [(a, a + msz)] m m' /\ mem_inv bsegs m'
    /\ SENV tp TSD CTX TH m' /\ RENV g b244 m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' 1221016 [C8 (wz 4096); C8 (wz pa); C8 (wz pa)]
    /\ rw_cells bsegs m' 1221064 [C8 (wz nres); C8 (wz (nch - 1)); C8 (wz 0)]
    /\ stk bsegs m' 1221088 1221632 /\ rw_cells bsegs m' 1221632 [C8 (wz 0)] /\ stk bsegs m' 1221640 1221680
    /\ u64arr bsegs m' pa (wlist (rs_chunks chunks idx nch lst))
    /\ (idx < nch - 1 -> rw_cells bsegs m' (lst + 24) [C8 (wz idx)])
    /\ stk bsegs m' (TH + 2800) (TH + 3168)
    /\ u8arr bsegs m' (sh a) (repeat (b8 0) (Z.to_nat (msz / 8)))
    /\ (forall x : word, a <= bv_unsigned x < a + msz -> m' x = None).

